with orders_by_store as (select store_id, round((100 * sum(case when channel = 'mobile' then 1 else 0 end)) / count(*), 1) pct_mobile, count(case when channel = 'partner' then 1 end) partner_count from orders group by store_id) select s.id, s.opened_date, obs.pct_mobile, obs.partner_count from stores s join orders_by_store obs on s.id = obs.store_id where obs.pct_mobile >= 38 order by s.id desc limit 10;
